import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    scope {
        let a = task effect io {
            io.println("a1")
            io.println("a2")
        }
        let b = task effect io {
            io.println("b1")
            io.println("b2")
        }
        let _ = a.await()
        let _ = b.await()
    }
    return Ok(())
}
